<?php
require __DIR__.'/../includes/bootstrap.php';require_login();
if(user()['role']==='admin'){$orders=db()->query('SELECT o.*,u.name cashier FROM orders o JOIN users u ON u.id=o.cashier_id ORDER BY o.id DESC')->fetchAll();$heading='All Sales History';}else{$s=db()->prepare('SELECT o.*,u.name cashier FROM orders o JOIN users u ON u.id=o.cashier_id WHERE o.cashier_id=? ORDER BY o.id DESC');$s->execute([user()['id']]);$orders=$s->fetchAll();$heading='My Sales History';}
$pageTitle='Sales History';require __DIR__.'/../includes/header.php';?>
<h1 class="h3 mb-3"><?=e($heading)?></h1><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Receipt</th><?php if(user()['role']==='admin'):?><th>Cashier</th><?php endif;?><th>Total</th><th>Payment</th><th>Amount Paid</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="receipt.php?id=<?=$o['id']?>"><?=e($o['receipt_number'])?></a></td><?php if(user()['role']==='admin'):?><td><?=e($o['cashier'])?></td><?php endif;?><td><?=money($o['grand_total'])?></td><td><?=e(strtoupper($o['payment_method']))?></td><td><?=money($o['amount_paid'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="<?=user()['role']==='admin'?'6':'5'?>" class="text-muted">No completed sales yet. Complete a checkout from POS first.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';
